import subprocess, json, re; from datetime import datetime; print('[*] Iniciando escaneo REAL en el segmento 192.168.1.0/24...'); out = subprocess.check_output('arp -a', shell=True).decode('cp1252'); IPs = re.findall(r'(192\.168\.1\.\d+)\s+([0-9a-f-]+)', out); mapa = [{'ip': ip, 'mac': mac, 'status': 'activo', 'ultima_conexion': datetime.now().isoformat()} for ip, mac in IPs if ip != '192.168.1.255']; json.dump(mapa, open('mapa_red.json', 'w'), indent=4); print(f'[+] Escaneo completado. {len(mapa)} dispositivos REALES guardados en mapa_red.json.')
